export const LISTENING = {
  1: [
    { topic: "Patrol orders — route and timing", passage: "All call signs, this is Zero. Routine patrol along Route Blue will depart at fourteen forty-five. Estimated return time is seventeen hundred. All vehicles must be fuelled and ready by fourteen fifteen. Any questions, contact the duty officer. Zero, out.", question: "By what time must vehicles be ready?", options: ["14:45 — departure time", "17:00 — return time", "14:15 — readiness time", "14:00 — one hour early"], answer: 2, ex: "Vehicles must be ready by 14:15 — 30 minutes before the 14:45 departure. Never confuse readiness time with departure time." },
    { topic: "Tannoy — Quick Reaction Force", passage: "Attention, attention. All personnel assigned to the Quick Reaction Force are to report to the vehicle park at oh-six-hundred tomorrow morning. Bring your personal weapon, full combat kit, and two days rations. Attendance is mandatory. Acknowledge receipt to Sergeant Kim at extension two-four-seven.", question: "Where should Quick Reaction Force personnel report?", options: ["The operations room", "Sergeant Kim's office", "The vehicle park", "The armoury"], answer: 2, ex: "QRF personnel must report to the vehicle park. Extension 247 is for confirmation only — a common distractor at Level 1." },
    { topic: "Casualty report — medevac request", passage: "Sunray, this is Bravo Two. We have one casualty, non-life-threatening, suspected broken ankle. Casualty is male, approximately twenty-five years old. We are at grid four-four-seven Echo. Request medical evacuation. Over.", question: "What is the nature of the casualty's injury?", options: ["Life-threatening head wound", "Broken leg", "Suspected broken ankle", "Chest injury"], answer: 2, ex: "The injury is a suspected broken ankle. 'Suspected' means not yet confirmed. The injury is also non-life-threatening — a key detail at Level 1." },
    { topic: "Supply confirmation", passage: "Hello, this is the supply sergeant from Alpha Company. We need to request forty litres of diesel, ten cases of water, and spare batteries for the radios. Can this be delivered by sixteen hundred today? Confirmed. Delivery will be at fifteen thirty.", question: "When will the supplies be delivered?", options: ["16:00 — as requested", "15:30 — confirmed delivery", "15:00 — one hour early", "End of day"], answer: 1, ex: "Delivery confirmed at 15:30, although the request was for 16:00. Tests whether you heard the confirmed time vs the requested time — a typical Level 1 attention task." },
    { topic: "Weather briefing", passage: "Good morning. The weather forecast for today is as follows. Temperature will reach eighteen degrees Celsius. Wind is from the west at fifteen kilometres per hour. Light rain is expected after eleven hundred. Visibility remains good. End of forecast.", question: "When is rain expected to begin?", options: ["At zero seven hundred", "After eleven hundred", "In the afternoon", "After sunset"], answer: 1, ex: "Light rain is expected after 11:00. Direct time retrieval — a common Level 1 listening task." },
    { topic: "Daily briefing", passage: "Good morning, team. Today's schedule is as follows. Physical training begins at zero five thirty. Breakfast at zero seven hundred. Briefing at zero eight hundred. Field exercise from zero nine hundred to twelve hundred. Lunch at twelve thirty. Equipment maintenance in the afternoon. Any questions?", question: "What activity follows the morning briefing?", options: ["Physical training", "Breakfast", "Field exercise", "Lunch"], answer: 2, ex: "Field exercise follows the briefing, running from 09:00 to 12:00. Sequence comprehension at Level 1." },
    { topic: "Personnel announcement", passage: "Attention all personnel. Lieutenant Smith has been promoted to the rank of Captain. The promotion ceremony will take place this Friday at ten hundred in the parade ground. All officers are invited to attend. Dress uniform is required. That is all.", question: "What rank has Lieutenant Smith been promoted to?", options: ["Major", "Colonel", "Captain", "Sergeant"], answer: 2, ex: "Promoted to Captain. The ceremony details are distractors — focus on what was actually said about the promotion." },
    { topic: "Radio check procedure", passage: "All stations, this is Hotel Six. Radio check, over. Hotel One, loud and clear, over. Hotel Two, loud and clear, over. Hotel Three, you are weak but readable, please change to alternate frequency. Hotel Six, all stations roger. Out.", question: "Which station was asked to change frequency?", options: ["Hotel One", "Hotel Two", "Hotel Three", "Hotel Six"], answer: 2, ex: "Hotel Three was weak but readable, so was asked to change to alternate frequency. Note: this is a key NATO radio procedure detail at Level 1." },
    { topic: "Mess hall information", passage: "Attention all personnel. The mess hall serves three meals per day. Breakfast is from zero six hundred to zero seven hundred. Lunch is from twelve hundred to thirteen thirty. Dinner is from eighteen hundred to nineteen hundred. Hot drinks are available all day from the coffee machine. End of message.", question: "Until what time is lunch served?", options: ["12:00", "13:00", "13:30", "14:00"], answer: 2, ex: "Lunch ends at 13:30. Pay attention to start time vs end time — Level 1 tests precise time boundaries." },
    { topic: "Guard duty assignment", passage: "Private Williams, you are assigned to guard duty tonight. Your shift begins at twenty-two hundred and ends at zero two hundred. You will be at Gate Two. Corporal Brown will relieve you. You must arrive ten minutes early. Acknowledged?", question: "Where will Private Williams be on guard duty?", options: ["Gate One", "Gate Two", "Gate Three", "The main entrance"], answer: 1, ex: "Private Williams will be at Gate Two. Don't confuse with the relieving guard (Corporal Brown) — location vs personnel are different details." },
    { topic: "Vehicle inspection reminder", passage: "Reminder to all drivers. Daily vehicle inspection must be completed before any vehicle is used. Check fuel levels, tyre pressure, oil, and lights. Any faults must be reported to the motor sergeant immediately. Inspection takes about ten minutes. End of message.", question: "Who must drivers report faults to?", options: ["The platoon commander", "The motor sergeant", "The duty officer", "The base commander"], answer: 1, ex: "Faults must be reported to the motor sergeant. Specific role identification — common at Level 1." },
    { topic: "Document handling instruction", passage: "Attention security staff. Classified documents must be kept in the secure cabinet at all times. Only authorised personnel may access them. The cabinet key is held by the duty officer. All access must be recorded in the security log. Failure to comply will result in disciplinary action.", question: "Who holds the key to the secure cabinet?", options: ["The base commander", "The intelligence officer", "The duty officer", "The military police"], answer: 2, ex: "The cabinet key is held by the duty officer. Specific responsibility identification at Level 1." },
    { topic: "Equipment issue", passage: "Soldiers reporting to the stores must bring their identification card and unit slip. Equipment issued today includes combat helmets, body armour, and night vision goggles. The stores are open from zero eight hundred until sixteen hundred. Bring your kit list with you.", question: "Until what time are the stores open?", options: ["12:00", "14:00", "16:00", "18:00"], answer: 2, ex: "The stores close at 16:00. Direct time retrieval — Level 1 standard." },
    { topic: "Communication equipment briefing", passage: "Listen carefully. Each squad will receive one radio. The radio operates on the assigned frequency only. Batteries must be charged every twenty-four hours. Spare batteries are available from the signals stores. Do not change frequency without authorisation. Any questions, see the signals officer.", question: "How often must batteries be charged?", options: ["Every twelve hours", "Every twenty-four hours", "Every forty-eight hours", "Once a week"], answer: 1, ex: "Batteries must be charged every 24 hours. Specific maintenance interval — Level 1 detail retrieval." },
    { topic: "Visitor procedures briefing", passage: "Gate guards listen up. All visitors must report to you. They must show identification and state the purpose of their visit. Contact the unit being visited before allowing entry. Visitors will receive a temporary pass and an escort. No exceptions to this procedure.", question: "What must visitors show at the gate?", options: ["A military pass", "Identification", "A travel permit", "Their phone"], answer: 1, ex: "Visitors must show identification. The general term is used — not specifically passport or military ID." },
  ],
  2: [
    { topic: "Intelligence briefing — bridge surveillance", passage: "Good morning. I am the intelligence officer for Task Force Kestrel. The current threat level in our area of operations is assessed as moderate. Overnight reconnaissance reported a vehicle with unknown markings travelling south along Route Orange at approximately oh-three-hundred. The vehicle stopped near the bridge at grid five-five-two Foxtrot for approximately twenty minutes before continuing south. We assess this as likely reconnaissance activity. All patrols are advised to approach the bridge area with caution and report any unusual activity immediately.", question: "Why does the intelligence officer advise caution near the bridge?", options: ["The bridge has been structurally damaged", "Enemy forces have been confirmed in the area", "The area may have been subject to hostile reconnaissance", "An improvised explosive device was found nearby"], answer: 2, ex: "The vehicle stopped near the bridge, assessed as likely reconnaissance activity. Caution follows from suspected hostile interest — not a confirmed enemy presence." },
    { topic: "Checkpoint orders — documentation", passage: "Listen carefully. The mission is to establish a vehicle checkpoint on Route Amber at grid three-three-zero Delta. The checkpoint will be operational from zero seven hundred to nineteen hundred. All vehicles will be stopped and occupants identification checked. Vehicles carrying military equipment require special authorisation documents. Any vehicle lacking correct documentation will be held pending further instructions from headquarters. At no time are weapons to be pointed at civilian vehicles during routine checks.", question: "What happens to vehicles without correct documentation?", options: ["They are immediately turned back", "They are escorted to headquarters", "They are held pending further instructions from headquarters", "Their occupants are arrested"], answer: 2, ex: "Vehicles lacking correct documentation are held pending further instructions. 'Pending' = while waiting for. Standard Level 2 procedure comprehension." },
    { topic: "Aerial reconnaissance — sortie debrief", passage: "The reconnaissance sortie departed at oh-six-fifteen and covered the designated area in the northern sector. Imagery was collected at three waypoints as planned. At waypoint Bravo, the crew observed a concentration of approximately thirty vehicles in a treeline approximately two kilometres east of the road. The vehicles appeared to be military trucks. The sortie recovered at oh-nine-ten without incident. Full imagery analysis will be completed within four hours.", question: "What did the crew observe at waypoint Bravo?", options: ["An empty treeline east of the road", "Approximately thirty military trucks in a treeline", "A bridge under construction", "A civilian convoy heading north"], answer: 1, ex: "At waypoint Bravo, the crew observed approximately thirty vehicles, two kilometres east of the road, appearing to be military trucks. Full detail retrieval combining location, number, and nature." },
    { topic: "Civil-military liaison meeting", passage: "Thank you for coming today, Mister Mayor. I want to assure you that our troops are here to support the local community, not to interfere in civilian life. We have established a liaison office at the town hall where residents can raise concerns directly with my staff. Our engineers will begin work on repairing the water supply on Monday. We expect the repairs to take approximately three days.", question: "How long will the water supply repairs take?", options: ["One day", "Two days", "Three days", "One week"], answer: 2, ex: "Repairs will take approximately three days. 'Approximately' = roughly, about. Level 2 listening tests comprehension of spoken estimates." },
    { topic: "Operational orders — patrol mission", passage: "The mission is to conduct a vehicle patrol along Route Yellow. Patrol composition will be three vehicles. Departure time is zero eight hundred. Estimated patrol duration is six hours. Maintain radio contact with headquarters every thirty minutes. Report any unusual activity immediately. Rules of engagement remain unchanged. Return to base by fourteen hundred.", question: "How often must the patrol report to headquarters?", options: ["Every fifteen minutes", "Every thirty minutes", "Every hour", "Only when contact is made"], answer: 1, ex: "Radio contact every 30 minutes. Communication intervals are commonly tested at Level 2." },
    { topic: "Security briefing", passage: "Following recent incidents, security procedures have been updated. All personnel entering the base must show their identification card. Vehicles will undergo inspection by the gate guards. Bags must be opened for inspection. These procedures apply to all personnel without exception, including senior officers. Compliance is mandatory.", question: "Who do the new security procedures apply to?", options: ["Only junior personnel", "Only visitors", "All personnel including senior officers", "Only personnel from outside the unit"], answer: 2, ex: "Procedures apply to all personnel without exception, including senior officers. Tests understanding of universal application of rules." },
    { topic: "Weather impact briefing", passage: "Severe weather is expected over the next twenty-four hours. Heavy snow and strong winds will affect operations across the entire area. All non-essential outdoor activities are postponed. Vehicle movement is restricted to essential operations only. Patrols will use the alternative northern route which remains accessible. Monitor weather updates every two hours.", question: "What is the situation regarding patrols?", options: ["All patrols are cancelled", "Patrols continue on the original route", "Patrols will use the alternative northern route", "Only foot patrols are permitted"], answer: 2, ex: "Patrols will use the alternative northern route, which remains accessible. Conditional adaptation is a key Level 2 listening skill." },
    { topic: "Medical evacuation procedure", passage: "Listen up. Medical evacuation procedures have been updated. For all casualties, first call the medical centre at extension two-zero-six. Provide casualty number, type of injury, and grid location. The medical team will despatch an ambulance within five minutes. Helicopter evacuation is available for serious cases requiring movement to the regional hospital.", question: "When is helicopter evacuation available?", options: ["For all casualties", "For serious cases requiring movement to the regional hospital", "Only at night", "Only during weekday operations"], answer: 1, ex: "Helicopter evacuation is available for serious cases requiring transfer to the regional hospital. Conditions for specialised resources are tested at Level 2." },
    { topic: "Joint exercise briefing", passage: "Welcome to the multinational exercise briefing. This exercise involves forces from four nations. The training objective is to improve interoperability between participating units. The exercise lasts ten days. Live-fire training will be conducted only at designated ranges and only with proper safety supervision. Cultural awareness briefings are scheduled for tomorrow morning.", question: "What is the main objective of the exercise?", options: ["To test new equipment", "To improve interoperability between units", "To train new recruits", "To evaluate individual performance"], answer: 1, ex: "The training objective is to improve interoperability. 'Interoperability' is a core NATO concept tested across all levels." },
    { topic: "Patrol incident report", passage: "Headquarters, this is Patrol Three reporting an incident. At approximately fourteen-thirty, while patrolling Route Green near the village, we encountered a civilian crowd blocking the road. The crowd was protesting peacefully against recent fuel price increases. We did not engage. We took the alternative route via the bridge and continued the mission. No casualties or damage. Patrol Three, out.", question: "How did the patrol respond to the crowd?", options: ["They dispersed the crowd", "They did not engage and took an alternative route", "They called for reinforcements", "They returned to base immediately"], answer: 1, ex: "The patrol did not engage and took the alternative route. Conflict avoidance and route adaptation — common Level 2 scenario." },
    { topic: "Equipment status report", passage: "Quartermaster, this is Charlie Company reporting equipment status. Currently we have eighty percent of authorised equipment serviceable. The remaining twenty percent requires maintenance. Two vehicles are awaiting parts that should arrive Friday. Three radios have been sent for repair. Replacement equipment is expected within seven working days.", question: "What proportion of equipment requires maintenance?", options: ["Ten percent", "Twenty percent", "Thirty percent", "Forty percent"], answer: 1, ex: "Twenty percent requires maintenance. Specific percentages are common Level 2 listening targets." },
    { topic: "Logistical request", passage: "Headquarters, this is Bravo Company. Resupply request as follows. We require five hundred litres of fuel, two thousand rations, and ammunition for the planned exercise next week. Delivery should reach us by Wednesday. Our location is grid two-two-five Tango. Acknowledge receipt of this request, please.", question: "By when does Bravo Company need the supplies?", options: ["Today", "Tomorrow", "Wednesday", "End of next week"], answer: 2, ex: "Supplies needed by Wednesday for the planned exercise next week. Delivery deadlines are key Level 2 details." },
    { topic: "Reconnaissance debrief", passage: "Reconnaissance team reporting. We patrolled the eastern sector for six hours. Visibility was good throughout. We observed routine civilian activity in the village of Saint Mary. No military vehicles or personnel were seen. The bridge at grid one-one-eight is intact and passable. We recommend continued routine surveillance of the area. End of report.", question: "What does the reconnaissance team recommend?", options: ["Immediate withdrawal from the area", "Increased military presence", "Continued routine surveillance", "Civilian evacuation"], answer: 2, ex: "The team recommends continued routine surveillance. Recommendations following reconnaissance are commonly tested at Level 2." },
    { topic: "Search operation briefing", passage: "Today's mission is a search operation in the wooded area north of the river. We are looking for a missing civilian, last seen yesterday afternoon. The search area is divided into four sectors. Each platoon will search one sector. Maintain visual contact with neighbouring soldiers. Report any findings immediately. The search will continue until eighteen hundred or until the missing person is located.", question: "When will the search end?", options: ["At twelve hundred", "At fifteen hundred", "At eighteen hundred or when the person is found", "When weather conditions deteriorate"], answer: 2, ex: "The search ends at 18:00 or when the missing person is located, whichever comes first. Conditional time limits — Level 2 listening." },
    { topic: "Damage assessment", passage: "Following last night's storm, damage assessment is as follows. Three vehicles sustained minor damage from falling debris. The repair workshop has been flooded. Communications equipment is fully operational. The main building is undamaged. Estimated repair time is forty-eight hours. Reduced operational tempo is recommended during this period.", question: "What is the estimated repair time?", options: ["Twelve hours", "Twenty-four hours", "Forty-eight hours", "One week"], answer: 2, ex: "Estimated repair time is 48 hours. Specific durations following incidents are common Level 2 details." },
  ],
  3: [
    { topic: "NATO summit — deterrence posture briefing", passage: "Ladies and gentlemen, the summit communiqué reaffirms the alliance's commitment to collective defence under Article Five, while also emphasising the importance of burden sharing among member nations. There is growing consensus that defence spending should reach two percent of gross domestic product as a minimum, with several allies now committing to exceed this threshold. Of particular significance is the agreement to establish a new rapid reaction capability on the eastern flank, comprising pre-positioned equipment and a rotational troop presence. This represents a fundamental shift from the reassurance model to an enhanced deterrence posture. The implications for force planning will be substantial.", question: "What does the agreement on a rapid reaction capability in the east represent?", options: ["A reduction in NATO's overall defence budget", "A return to the Cold War deterrence model", "A shift from reassurance to enhanced deterrence", "A new framework for burden-sharing negotiations"], answer: 2, ex: "The agreement represents a fundamental shift from the reassurance model to an enhanced deterrence posture. Level 3 listening tests understanding of strategic significance, not just facts." },
    { topic: "Logistics conference — fuel vulnerability", passage: "Fuel consumption remains our greatest logistical vulnerability. In the current operational context, forward bases are consuming an average of twelve thousand litres of diesel per day, the majority of which is used for power generation rather than vehicle movement. Reducing this dependency requires both short-term solutions, such as improved generator efficiency, and longer-term investment in renewable energy sources. Solar installations at two forward bases have already reduced fuel demand by approximately eighteen percent, and we are planning to expand this initiative across all fixed installations within the next fiscal year.", question: "What has been the effect of solar installations at forward bases?", options: ["They have eliminated the need for diesel entirely", "They have reduced fuel demand by approximately eighteen percent", "They have been installed across all fixed installations", "They have improved vehicle fuel efficiency"], answer: 1, ex: "Solar installations have reduced fuel demand by approximately 18 percent. Level 3 tests precise quantified data extraction from longer audio." },
    { topic: "Media operations — press guidance briefing", passage: "Listen carefully. The commander's press statement will be released at fourteen hundred. Key messages are as follows. First, that all military actions have been conducted in full compliance with international law. Second, that civilian protection has been the paramount concern throughout the operation. Third, that we are working closely with humanitarian organisations to facilitate access to affected populations. You are not authorised to comment on operational timelines, casualty figures, or future intentions. Refer all media queries outside these key messages to the public affairs officer.", question: "What are personnel instructed NOT to comment on?", options: ["The legality of military operations", "The number of troops involved", "Operational timelines, casualty figures, and future intentions", "Relations with humanitarian organisations"], answer: 2, ex: "Personnel cannot comment on operational timelines, casualty figures, or future intentions. Three specific restricted topics — Level 3 tests ability to identify boundaries and restrictions." },
    { topic: "Strategic assessment briefing", passage: "Good afternoon. The strategic assessment for the current quarter identifies three principal challenges. First, the deterioration of the security environment along the eastern flank requires sustained military presence and enhanced deterrence measures. Second, hybrid threats targeting critical infrastructure have intensified and demand integrated civilian-military responses. Third, the strain on logistical systems caused by simultaneous operations in multiple theatres approaches the limits of current capacity. Resource allocation decisions must reflect these realities. The full report will be distributed by close of business tomorrow.", question: "What does the assessment identify regarding logistical systems?", options: ["They have unused spare capacity", "They are functioning normally", "They approach the limits of current capacity due to multiple theatres", "They have been completely overhauled"], answer: 2, ex: "Logistical systems approach the limits of current capacity due to simultaneous operations. Level 3 listening: tests understanding of strain and capacity limits." },
    { topic: "Doctrine update briefing", passage: "Recent operational experience has prompted significant revisions to alliance doctrine. The updated framework emphasises the integration of conventional, cyber, and information capabilities within unified operational concepts. National forces will be expected to develop competence across these domains rather than focusing narrowly on traditional military skills. Implementation will require investment in training, equipment, and personnel selection criteria. The transition timeline extends over five years, with initial certification of integrated units expected within eighteen months. Member nations are requested to identify lead units for participation in the certification programme.", question: "What is the expected timeline for initial certification of integrated units?", options: ["Six months", "Eighteen months", "Three years", "Five years"], answer: 1, ex: "Initial certification within 18 months, with the full transition over 5 years. Level 3 tests precise time references in complex announcements." },
    { topic: "Counter-terrorism analysis", passage: "The counter-terrorism analysis for this quarter highlights an evolving threat picture. Established networks have been substantially degraded through sustained pressure. However, the diffusion of operational capabilities has produced an increase in attacks by individuals or small cells with limited prior connections to organised groups. These actors typically employ readily available means and target locations selected for symbolic rather than strategic value. Detection and prevention require enhanced cooperation between intelligence and law enforcement agencies, supported by community engagement initiatives. Purely military responses are insufficient to address the contemporary threat.", question: "What does the analysis say about purely military responses?", options: ["They are the most effective approach", "They are insufficient to address the contemporary threat", "They should be expanded significantly", "They are no longer required"], answer: 1, ex: "Purely military responses are insufficient to address the contemporary threat. Level 3 listening tests recognition of comprehensive vs limited approaches." },
    { topic: "Allied cooperation briefing", passage: "Today's briefing addresses recent developments in allied cooperation. The integration of Finland and Sweden into alliance structures has progressed substantially over the past year. Force contributions, planning processes, and command arrangements have been updated to reflect their full participation. The strategic implications, particularly for operations in the Baltic and Arctic regions, are profound. Our planning assumptions require revision to account for the expanded operational geography and the additional capabilities now available to the alliance. Specific guidance for affected commands will follow this briefing.", question: "What does the briefing identify as requiring revision?", options: ["The alliance treaty", "Our planning assumptions", "National defence budgets", "Recruitment procedures"], answer: 1, ex: "Planning assumptions require revision to account for expanded geography and capabilities. Level 3 tests understanding of consequential changes following strategic events." },
    { topic: "Cyber incident briefing", passage: "Yesterday at twenty-three hundred, a cyber incident affecting our administrative networks was detected. Initial analysis indicates a sophisticated intrusion using techniques consistent with state-sponsored activity. Sensitive operational systems remained isolated and unaffected. The full extent of compromise is still being determined. Mitigation measures are in place. We expect operational impact to be minimal, although some administrative functions will operate at reduced efficiency for several days. Detailed technical briefings will be provided to affected units this afternoon.", question: "What is the expected operational impact?", options: ["Severe and prolonged", "Minimal", "Currently unknown", "Limited to combat units"], answer: 1, ex: "Operational impact is expected to be minimal, although administrative functions will operate at reduced efficiency. Level 3 tests differentiation between operational and administrative impact." },
    { topic: "Force generation briefing", passage: "The force generation conference identified shortfalls in three key capability areas. Combat support, particularly engineering and logistics, remains undermanned across multiple operations. Air mobility assets are committed at unsustainable levels with limited reserve capacity. Specialised personnel for emerging domains, including cyber and space operations, are in critically short supply. Member nations have been requested to review their contributions and identify potential additional commitments. The next force generation conference is scheduled for the autumn, when revised commitments will be consolidated.", question: "What is described as committed at unsustainable levels?", options: ["Combat support units", "Air mobility assets", "Specialised cyber personnel", "Engineering capabilities"], answer: 1, ex: "Air mobility assets are committed at unsustainable levels with limited reserve capacity. Level 3 listening tests differentiation between similar capability areas." },
    { topic: "Strategic partnership briefing", passage: "Strategic partnerships beyond the alliance continue to evolve in response to changing security dynamics. Cooperation with the Indo-Pacific democracies has expanded substantially, reflecting growing recognition of interconnected security challenges. Joint exercises, intelligence sharing, and dialogue mechanisms have been established or enhanced. Critics caution that overextension of alliance attention beyond the Euro-Atlantic area risks dilution of focus from primary collective defence responsibilities. Proponents argue that contemporary security cannot be neatly compartmentalised and that engagement with global partners enhances rather than detracts from regional security commitments.", question: "What argument do proponents of expanded global partnerships make?", options: ["The alliance should focus only on Europe", "Engagement with global partners enhances regional security", "Partnerships should be limited to military cooperation", "Indo-Pacific cooperation has been unsuccessful"], answer: 1, ex: "Proponents argue that engagement with global partners enhances rather than detracts from regional security commitments. Level 3 tests understanding of opposing arguments." },
    { topic: "Capability development update", passage: "Capability development priorities for the coming period focus on resilience, advanced technology integration, and force readiness. Resilience improvements address vulnerabilities exposed by recent crises, including supply chain dependencies and critical infrastructure protection. Advanced technology integration emphasises artificial intelligence applications, autonomous systems, and quantum-enabled capabilities. Force readiness measures aim to reduce response timelines for high-readiness units. Resource constraints require careful prioritisation among these competing demands. Member nations are encouraged to align national capability development with these alliance priorities.", question: "What do the resilience improvements address?", options: ["Only military equipment failures", "Vulnerabilities including supply chain dependencies and critical infrastructure", "Personnel training shortfalls", "Outdated communications systems"], answer: 1, ex: "Resilience improvements address vulnerabilities including supply chain dependencies and critical infrastructure protection. Level 3 tests scope identification across multiple categories." },
    { topic: "Operational risk assessment", passage: "The current operational risk assessment identifies elevated probability of incidents involving multiple actors in contested operational environments. Deconfliction mechanisms remain essential to prevent inadvertent escalation. Recent incidents involving close approaches between alliance and adversary forces have underscored the importance of clear procedures and rapid communication. Risk mitigation requires both technical measures, including improved identification systems, and procedural measures including agreed protocols for unplanned encounters. Training emphasis on these procedures has been increased across affected units.", question: "What does the assessment identify as essential?", options: ["Increased military presence", "Deconfliction mechanisms to prevent inadvertent escalation", "Withdrawal from contested areas", "Public diplomatic statements"], answer: 1, ex: "Deconfliction mechanisms are essential to prevent inadvertent escalation. Level 3 listening tests recognition of risk mitigation principles." },
    { topic: "Logistics modernisation briefing", passage: "Logistics modernisation initiatives address persistent challenges identified during recent operations. The current system, characterised by national stovepipes and limited interoperability, generates inefficiencies and creates vulnerabilities. Multinational logistics arrangements offer significant potential improvements but require political commitment from contributing nations. The pilot programme launched last year demonstrated achievable cost savings of approximately fifteen percent through pooled supply arrangements. Expansion of the pilot to additional categories of equipment is under active consideration. Implementation challenges include reconciling different national procurement procedures and quality standards.", question: "What did the pilot programme demonstrate?", options: ["Cost savings of approximately fifteen percent", "Failure of multinational arrangements", "The need for purely national logistics", "Quality problems with shared supplies"], answer: 0, ex: "The pilot programme demonstrated cost savings of approximately 15 percent through pooled supply arrangements. Level 3 tests precise quantitative findings." },
    { topic: "Information environment briefing", passage: "The information environment continues to be a critical dimension of contemporary operations. Adversary information activities target alliance cohesion, undermine public support for military engagements, and create operational uncertainty. Effective response requires both reactive capabilities, including rapid fact-checking and counter-messaging, and proactive measures including narrative shaping and resilience building. Our democratic values impose constraints on certain types of information activities that authoritarian adversaries do not face. These constraints must be respected even as we develop more effective approaches within them. Strategic communications competence is now considered essential at all command levels.", question: "What does the briefing say about democratic values?", options: ["They have no impact on information operations", "They impose constraints that must be respected", "They are obstacles to be overcome", "They are no longer relevant"], answer: 1, ex: "Democratic values impose constraints that must be respected even while developing more effective approaches. Level 3 tests recognition of value-based constraints in operational contexts." },
    { topic: "Future force concept briefing", passage: "The future force concept envisions integrated operations across all domains, supported by ubiquitous data sharing and artificial intelligence-enabled decision support. Human-machine teaming will become increasingly central to operational effectiveness. Traditional distinctions between combat and support functions will blur as automation reshapes operational tasks. Personnel skills must evolve correspondingly, with technical literacy required across all roles. Training systems require fundamental redesign to develop and maintain these new competencies. Investment in this transformation cannot be delayed without accepting growing capability gaps relative to potential adversaries.", question: "What does the concept say about traditional combat-support distinctions?", options: ["They will become more rigid", "They will blur as automation reshapes operational tasks", "They will be eliminated entirely", "They remain unchanged"], answer: 1, ex: "Traditional distinctions will blur as automation reshapes operational tasks. Level 3 tests recognition of evolving operational concepts." },
  ],
  4: [
    { topic: "Information warfare — strategic communications", passage: "The information environment has become a decisive domain of competition that precedes, accompanies, and outlasts kinetic operations. Adversaries exploit information asymmetries to undermine alliance cohesion, erode public support for military engagement, and create strategic paralysis in decision-making processes. Effective strategic communications requires not merely rapid response to disinformation, but the proactive shaping of the narrative space through credible, consistent, and coordinated messaging. The challenge, however, is that the alliance's commitment to democratic values and transparency imposes constraints on information operations that adversaries operating under authoritarian frameworks do not face. This asymmetry is fundamental and not amenable to technical solutions alone.", question: "What constraint does the speaker identify as limiting alliance information operations?", options: ["The high cost of modern communications technology", "The difficulty of coordinating messages across member nations", "Commitment to democratic values and transparency", "The speed at which disinformation spreads online"], answer: 2, ex: "The alliance's commitment to democratic values and transparency imposes constraints that adversaries under authoritarian frameworks do not face. Level 4 tests understanding of nuanced tension between strategic goals and foundational values." },
    { topic: "Multi-domain operations doctrine lecture", passage: "Multi-domain operations represent a paradigmatic shift in how we conceptualise and execute military campaigns. Rather than treating air, land, sea, space, and cyber as parallel but largely independent domains, the multi-domain framework seeks to exploit convergence — the simultaneous application of effects across domains to create dilemmas for the adversary that cannot be resolved by acting in any single domain. Air power, by virtue of its speed, reach, and flexibility, remains the principal enabler of cross-domain synergy. However, realising this potential demands a level of inter-service integration and digital interoperability that most allied nations are still developing. The transition is not merely technical but conceptual.", question: "What does the concept of convergence in multi-domain operations mean?", options: ["Merging all military services into a single unified force", "Concentrating forces in one geographic area", "Simultaneously applying effects across domains to create irresolvable dilemmas", "Using air power as the sole means of military action"], answer: 2, ex: "Convergence is defined as the simultaneous application of effects across domains creating dilemmas that cannot be resolved by acting in any single domain. Level 4 requires correctly applying specialist terminology defined within the audio." },
    { topic: "Strategic stability seminar", passage: "Strategic stability between nuclear-armed great powers has historically rested upon a combination of mutual vulnerability, transparency mechanisms, and arms control agreements that constrain destabilising capabilities. The progressive erosion of this architecture has raised profound concerns about the increased risk of miscalculation during crises. Emerging technologies, including hypersonic weapons, autonomous systems, and counterspace capabilities, complicate traditional concepts of strategic stability by compressing decision timelines and blurring distinctions between conventional and nuclear capabilities. Restoring elements of the previous architecture appears unlikely in the near term given current geopolitical tensions. Nevertheless, the underlying logic that motivated previous agreements retains its essential validity.", question: "What does the speaker say about the underlying logic of arms control?", options: ["It has been completely discredited", "It retains its essential validity", "It applies only to nuclear weapons", "It requires complete trust between adversaries"], answer: 1, ex: "The underlying logic that motivated previous agreements retains its essential validity. Level 4 tests recognition of enduring principles despite changing circumstances." },
    { topic: "Hybrid threat analysis seminar", passage: "Contemporary hybrid threats exploit the seams of traditional security frameworks. Adversaries deliberately operate below the threshold of armed conflict, employing combinations of cyber operations, disinformation, economic coercion, and proxy forces to achieve strategic objectives without triggering decisive collective response. The challenge for defending alliances is fundamental. Response thresholds calibrated to deter conventional aggression may prove ineffective against more ambiguous threats. Yet lowering response thresholds risks unintended escalation in genuinely contested situations. Resolving this tension requires both improved attribution capabilities and political will to act on the basis of accumulated evidence rather than indisputable proof. Neither capability nor will is currently sufficient.", question: "What does the speaker say is currently insufficient?", options: ["Military spending", "Both attribution capabilities and political will", "International cooperation", "Cyber defence technology"], answer: 1, ex: "Both attribution capabilities and political will are currently insufficient — the speaker explicitly identifies neither as sufficient. Level 4 tests careful tracking of complex assertions." },
    { topic: "Deterrence theory lecture", passage: "Contemporary deterrence theory has evolved considerably from its Cold War origins, when nuclear-centric models predominated. The current strategic environment requires conceptual frameworks capable of addressing simultaneous challenges from peer competitors, regional powers, and non-state actors operating across the full spectrum of conflict. Tailored deterrence approaches recognise that what deters a nuclear-armed great power may be entirely irrelevant against a transnational terrorist organisation, and that what credibly threatens an authoritarian regime may not affect a democratic adversary's calculations. This proliferation of deterrence relationships imposes substantial demands on intelligence, capabilities, and policymaking capacity. The integrated deterrence concept seeks to consolidate these multiple requirements within a unified framework.", question: "What characterises tailored deterrence approaches?", options: ["Application of identical measures to all adversaries", "Recognition that different adversaries require different approaches", "Sole reliance on nuclear deterrence", "Withdrawal from deterrence relationships"], answer: 1, ex: "Tailored deterrence recognises that what deters one adversary may be entirely irrelevant against another. Level 4 tests recognition of differentiated strategic principles." },
    { topic: "Emerging technology assessment", passage: "Emerging and disruptive technologies present complex strategic challenges that defy easy resolution. Artificial intelligence, quantum computing, biotechnology, and autonomous systems will reshape military capabilities in ways that remain incompletely understood. The pace of technological development outstrips traditional acquisition and integration processes, creating pressure for institutional adaptation. Adversaries face similar challenges but may operate under fewer constraints in pursuing rapid integration. The competitive dynamic risks decisions driven more by anxiety about lagging behind than by careful assessment of operational utility. Maintaining technological advantage requires not merely investment but disciplined judgement about which capabilities genuinely enhance operational effectiveness rather than merely reflecting fashion within technology communities.", question: "What does the speaker warn against?", options: ["Investing in any new technology", "Decisions driven by anxiety about lagging rather than careful assessment", "International cooperation in technology development", "Maintaining technological advantages"], answer: 1, ex: "The speaker warns against decisions driven by anxiety about lagging behind rather than careful assessment of operational utility. Level 4 tests recognition of subtle warnings within otherwise positive frames." },
    { topic: "Resilience strategic concept", passage: "Resilience has emerged as a central concept in contemporary security thinking, reflecting recognition that prevention of all hostile actions is impossible and that the capacity to absorb, adapt to, and recover from hostile actions is therefore essential. Alliance doctrine identifies seven baseline resilience requirements covering critical infrastructure, civilian capabilities, and continuity of government. Implementation depends primarily upon national authorities, although coordination through alliance mechanisms enhances coherence and identifies gaps. Resilience requirements interact with traditional military capabilities in complex ways. Investments in resilience may reduce vulnerabilities that adversaries seek to exploit, thereby contributing to deterrence by denial. Conversely, evident gaps in resilience may incentivise hostile action by suggesting attractive targets.", question: "How does the speaker describe the relationship between resilience and deterrence?", options: ["Resilience and deterrence are unrelated concepts", "Resilience investments may contribute to deterrence by denial", "Resilience eliminates the need for deterrence", "Deterrence makes resilience unnecessary"], answer: 1, ex: "Investments in resilience may reduce vulnerabilities adversaries seek to exploit, contributing to deterrence by denial. Level 4 tests understanding of complex conceptual relationships." },
    { topic: "Burden sharing analysis seminar", passage: "Burden sharing within the alliance has been a perennial source of contention since NATO's establishment, but the debate has acquired new intensity in the contemporary period. The benchmark of two percent of gross domestic product, agreed at the Wales Summit, has become a politically charged metric despite its acknowledged limitations as a measure of meaningful contribution. Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made by member states. A nation might exceed the spending threshold while investing inefficiently in capabilities of marginal alliance utility, while another nation might fall below the threshold yet provide highly capable forces in critical operations. More sophisticated assessments incorporate measures of capability development, operational deployment, and acceptance of risk in alliance missions.", question: "What limitation of the spending metric does the speaker identify?", options: ["It is too difficult to calculate", "It captures neither quality of capabilities nor operational contributions", "It is rejected by most member states", "It encourages excessive defence spending"], answer: 1, ex: "Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made. Level 4 tests understanding of analytical critique." },
    { topic: "Civil-military relations lecture", passage: "Civil-military relations in democratic societies require continuous attention to maintain appropriate balance. Military expertise must inform decisions on use of force without supplanting civilian authority over fundamental questions of war and peace. Civilian leaders must engage substantively with military advice without micromanaging operational details. The boundary between strategic direction and operational interference is not always clear, and reasonable people disagree about specific cases. Political polarisation in some allied nations has placed additional strain on these relationships, as military leaders navigate environments where their professional advice may be politicised by partisan interests. Maintaining the apolitical character of military service is essential but increasingly challenging.", question: "What does the speaker say about civilian-military boundaries?", options: ["They are completely clear in all cases", "The boundary between strategic direction and operational interference is not always clear", "Civilian leaders should never engage with military advice", "Military leaders should always defer to politicians"], answer: 1, ex: "The boundary between strategic direction and operational interference is not always clear, and reasonable people disagree about specific cases. Level 4 recognition of analytical nuance." },
    { topic: "Nuclear posture debate", passage: "The debate over alliance nuclear posture has intensified following recent developments. Some advocate enhancements to current arrangements, including modernisation of dual-capable aircraft and consideration of expanded sharing arrangements with additional allies. Others argue that any expansion would prove escalatory and counterproductive, undermining strategic stability without enhancing deterrence. The middle position emphasises maintaining current arrangements while ensuring their continued credibility through investment in supporting capabilities. Resolution of this debate requires addressing not only military requirements but also political sustainability among diverse member states with varying historical perspectives on nuclear weapons. The debate is unlikely to reach definitive resolution.", question: "What does the middle position emphasise?", options: ["Significant expansion of nuclear arrangements", "Maintaining current arrangements while ensuring their credibility", "Complete elimination of nuclear weapons", "Withdrawal from nuclear sharing entirely"], answer: 1, ex: "The middle position emphasises maintaining current arrangements while ensuring continued credibility through investment in supporting capabilities. Level 4 distinguishes between three positions within a complex debate." },
    { topic: "Alliance solidarity assessment", passage: "Alliance solidarity faces continuous testing in the contemporary security environment. Traditional sources of cohesion, including shared threat perception and common values, remain operative but are subjected to centrifugal pressures from divergent national interests, varying threat assessments, and contested decisions about resource allocation. The capacity to maintain solidarity depends substantially upon the quality of consultation processes that allow legitimate national perspectives to be heard and accommodated within collective positions. When consultation is perceived as inadequate, decisions may be formally adopted but lack the substantive political weight necessary for effective implementation. The institutional health of consultation mechanisms is therefore strategically significant, although it receives less attention than questions of capability and posture.", question: "What does the speaker identify as receiving less attention than it deserves?", options: ["Capability development", "Force posture decisions", "The institutional health of consultation mechanisms", "Public diplomacy efforts"], answer: 2, ex: "The institutional health of consultation mechanisms is strategically significant, although it receives less attention than capability and posture. Level 4 tests recognition of underappreciated dimensions." },
    { topic: "Operational learning seminar", passage: "Effective adaptation in operations requires institutionalised processes for capturing and disseminating lessons learned. The challenge is not merely technical but cultural. Organisations may resist acknowledging failures or limitations that would inform future improvements. Senior leaders may be reluctant to associate themselves with assessments that imply previous decisions were flawed. Career incentives may discourage analytical honesty about operational difficulties. Overcoming these tendencies requires explicit institutional commitment to learning, supported by procedures that protect the integrity of analytical processes from political pressures. Even with strong commitment, the gap between identifying lessons and implementing institutional changes that genuinely reflect those lessons can be substantial.", question: "What does the speaker identify as the principal challenge in operational learning?", options: ["Lack of analytical capability", "Insufficient resources for analysis", "Cultural resistance and career incentives", "Excessive standardisation of procedures"], answer: 2, ex: "Cultural resistance, organisational reluctance to acknowledge failures, and career incentives are the principal challenges. Level 4 recognises multiple intersecting non-technical factors." },
    { topic: "Strategic foresight briefing", passage: "Strategic foresight processes seek to identify plausible future developments that should inform current decisions. The methodology has matured considerably, drawing upon scenario planning, expert elicitation, and quantitative modelling techniques. However, fundamental epistemological limitations constrain what foresight can achieve. Truly novel developments by definition resist anticipation. Discontinuities in major trends, often retrospectively obvious, prove elusive in prospective analysis. Effective use of foresight therefore requires acknowledgement of its limitations alongside its contributions. Treating scenario projections as predictions, rather than as devices for stretching analytical imagination, can produce false confidence that distorts decision-making in the face of genuinely uncertain futures.", question: "What warning does the speaker offer about scenario projections?", options: ["They are completely unreliable", "Treating them as predictions can produce false confidence", "They should be ignored entirely", "They predict the future accurately"], answer: 1, ex: "Treating scenario projections as predictions can produce false confidence that distorts decision-making. Level 4 tests recognition of methodological limitations." },
    { topic: "Geopolitical assessment", passage: "The contemporary geopolitical environment combines elements of continuity and rupture in ways that resist simple characterisation. Great power competition has reasserted itself as a defining feature of international relations, displacing earlier expectations of converging interests among major powers. Yet this competition occurs within structures of economic interdependence and shared global challenges that distinguish current circumstances from earlier eras of great power rivalry. Climate change, pandemic risks, and technological transformation create both areas of necessary cooperation and new dimensions of competition. Navigating this environment requires conceptual frameworks that accommodate complexity rather than seeking false clarity through simplified analogies to earlier periods. Such frameworks remain underdeveloped.", question: "What does the speaker say about conceptual frameworks for navigating the current environment?", options: ["They are fully developed", "They remain underdeveloped", "They should rely on historical analogies", "They are unnecessary"], answer: 1, ex: "Conceptual frameworks accommodating complexity rather than simplified historical analogies remain underdeveloped. Level 4 tests recognition of intellectual gaps in strategic thinking." },
    { topic: "Decision-making under uncertainty", passage: "Strategic decisions must routinely be made under conditions of substantial uncertainty about both adversary intentions and the consequences of alternative courses of action. The temptation to defer decisions until uncertainty is reduced often proves illusory, since waiting itself constitutes a decision with its own consequences. Effective decision-making under uncertainty requires explicit consideration of alternative possibilities, robust hedging strategies that perform acceptably across multiple scenarios, and willingness to revise initial judgements as additional information becomes available. None of these requirements is easily met. Cognitive biases, organisational pressures, and political constraints all push toward false certainty and resistance to revision. Cultivating the capacity for genuine decision-making under uncertainty is among the most demanding requirements of strategic leadership.", question: "What does the speaker identify as among the most demanding requirements of strategic leadership?", options: ["Avoiding all uncertainty", "Cultivating genuine decision-making under uncertainty", "Following established procedures", "Maximising military capability"], answer: 1, ex: "Cultivating the capacity for genuine decision-making under uncertainty is among the most demanding requirements of strategic leadership. Level 4 tests recognition of subtle leadership challenges." },
  ],
};

// JFLT Question Database — Reading
// 15 questions per level × 4 levels = 60 questions
// Following STANAG 6001 specifications:
// - L1: ~50 words, simple facts
// - L2: ~150 words, conditions/restrictions
// - L3: ~300 words, abstract/analytical
