export const READING = {
  1: [
    { topic: "Checkpoint procedures", passage: "Corporal Davies is on duty at Checkpoint Alpha. He stops a civilian vehicle and asks the driver to show identification. The driver presents a passport. The corporal checks the document and records the entry time as 0820. He then waves the vehicle through.", question: "What time did the vehicle pass through the checkpoint?", options: ["0800", "0820", "0830", "0840"], answer: 1, ex: "The entry time is explicitly stated as 0820. Level 1 Reading tests ability to find specific facts in short texts (~50 words)." },
    { topic: "Daily military routine", passage: "The morning briefing begins at 0700. All officers must be present. Sergeant Major Rodriguez will present the daily schedule. After the briefing, personnel will proceed to their assigned posts. Breakfast is available in the mess hall until 0630.", question: "When does the morning briefing start?", options: ["0600", "0630", "0700", "0800"], answer: 2, ex: "'The morning briefing begins at 0700.' Note that breakfast ends BEFORE the briefing — a common Level 1 trap testing careful reading." },
    { topic: "Equipment and supplies", passage: "The supply depot received a shipment of 200 ration packs, 50 first aid kits, and 30 radio batteries. The items were checked and stored. The depot commander signed the delivery receipt at 1400.", question: "How many first aid kits were received?", options: ["200", "50", "30", "100"], answer: 1, ex: "'50 first aid kits' — Level 1 tests precise number retrieval. Don't confuse with 200 (ration packs) or 30 (batteries)." },
    { topic: "Medical — first aid", passage: "Private Johnson was injured during training. He reported to the medical centre at 1530. The medic treated a cut on his left hand. Johnson was cleared to return to duty the following morning.", question: "Which part of Private Johnson's body was injured?", options: ["Right hand", "Left arm", "Left hand", "Right arm"], answer: 2, ex: "'A cut on his left hand' — small details like left vs right are commonly tested at Level 1." },
    { topic: "Weather report", passage: "Tomorrow's weather forecast: cloudy in the morning with light rain expected after 1100. Temperature will reach 18 degrees Celsius. Wind from the west at 15 kilometres per hour. Visibility good. The weather may affect afternoon training activities.", question: "When is rain expected to begin?", options: ["In the early morning", "After 1100", "In the evening", "At midnight"], answer: 1, ex: "'Light rain expected after 1100' — straightforward time retrieval. 'After 1100' means from 1100 onwards." },
    { topic: "Personnel announcement", passage: "Lieutenant Smith has been promoted to the rank of Captain. The promotion ceremony will take place on Friday at 1000 in the parade ground. All officers are invited to attend. Dress uniform is required.", question: "What rank has Lieutenant Smith been promoted to?", options: ["Major", "Colonel", "Captain", "Sergeant"], answer: 2, ex: "'Promoted to the rank of Captain' — direct fact retrieval. Don't be distracted by the original rank (Lieutenant)." },
    { topic: "Training schedule", passage: "The new recruits will begin physical training at 0500 daily. The training session lasts two hours. Breakfast follows at 0730. Weapon training starts at 0900 and continues until lunch.", question: "How long is the morning physical training session?", options: ["One hour", "Two hours", "Three hours", "Half an hour"], answer: 1, ex: "'The training session lasts two hours' — direct fact retrieval. Note that 0500–0700 = 2 hours, then breakfast at 0730." },
    { topic: "Vehicle inspection", passage: "All military vehicles must undergo daily inspection before use. Drivers check fuel levels, tyre pressure, oil, and lights. Any faults must be reported to the motor sergeant immediately. Inspection takes about ten minutes.", question: "Who must drivers report faults to?", options: ["The platoon commander", "The motor sergeant", "The duty officer", "The base commander"], answer: 1, ex: "'Any faults must be reported to the motor sergeant immediately' — specific role identification at Level 1." },
    { topic: "Mess hall information", passage: "The mess hall serves three meals per day. Breakfast is from 0600 to 0700. Lunch is from 1200 to 1330. Dinner is from 1800 to 1900. Hot drinks are available all day from the coffee machine.", question: "Until what time is lunch served?", options: ["1200", "1300", "1330", "1400"], answer: 2, ex: "'Lunch is from 1200 to 1330' — pay attention to start vs end time. 1330 is the closing time." },
    { topic: "Guard duty roster", passage: "Private Williams is assigned to guard duty tonight. His shift begins at 2200 and ends at 0200. He will be at Gate Two. Corporal Brown will relieve him. Williams must arrive ten minutes early.", question: "Where will Private Williams be on guard duty?", options: ["Gate One", "Gate Two", "Gate Three", "The main entrance"], answer: 1, ex: "'He will be at Gate Two' — location retrieval. Don't confuse with the relieving guard (Corporal Brown)." },
    { topic: "Radio check", passage: "All units perform a radio check at 0800 each morning. The check confirms equipment is working. Units report their call sign and signal strength. Headquarters records the results in the daily log.", question: "What time is the daily radio check?", options: ["0700", "0800", "0900", "1000"], answer: 1, ex: "'A radio check at 0800 each morning' — specific time retrieval. 'Each morning' confirms it is a routine event." },
    { topic: "Document handling", passage: "Classified documents must be kept in the secure cabinet. Only authorised personnel may access them. The cabinet key is held by the duty officer. All access must be recorded in the security log.", question: "Who holds the key to the secure cabinet?", options: ["The base commander", "The intelligence officer", "The duty officer", "The military police"], answer: 2, ex: "'The cabinet key is held by the duty officer' — specific responsibility identification." },
    { topic: "Uniform regulations", passage: "Combat uniform is worn during operations and field training. Service dress is required for office work and formal duties. Physical training kit is worn only during sports and PT sessions. Civilian clothes are not permitted on duty.", question: "When is service dress required?", options: ["During field training", "During sports", "For office work and formal duties", "On weekends"], answer: 2, ex: "'Service dress is required for office work and formal duties' — matching uniform type to occasion." },
    { topic: "Communication equipment", passage: "Each squad receives one PRC-77 radio. The radio operates on the assigned frequency. Batteries must be charged every 24 hours. Spare batteries are available from the signals stores.", question: "How often must batteries be charged?", options: ["Every 12 hours", "Every 24 hours", "Every 48 hours", "Once a week"], answer: 1, ex: "'Batteries must be charged every 24 hours' — specific maintenance interval." },
    { topic: "Visitor procedures", passage: "All visitors must report to the gate guard. They must show identification and state the purpose of their visit. The guard contacts the unit being visited. Visitors receive a temporary pass and an escort.", question: "What must visitors show at the gate?", options: ["A military pass", "Identification", "A travel permit", "Their phone"], answer: 1, ex: "'They must show identification' — what is required at entry. Note 'identification' is the general term, not specifically passport or military pass." },
  ],
  2: [
    { topic: "Rules of engagement — Kosovo", passage: "KFOR troops deployed in Kosovo operate under strict rules of engagement. Soldiers are authorised to use force only in self-defence or to protect civilians under imminent threat. Any use of force must be reported immediately to the commanding officer and documented in the duty log. Troops are reminded that all actions must comply with international humanitarian law.", question: "Under what circumstances may KFOR soldiers use force?", options: ["At any time they consider necessary", "Only in self-defence or to protect civilians under imminent threat", "After receiving written authorisation", "Only when ordered by a superior officer"], answer: 1, ex: "'Authorised to use force only in self-defence or to protect civilians under imminent threat' — Level 2 tests understanding of conditions and restrictions, not just isolated facts." },
    { topic: "Convoy logistics", passage: "The logistics convoy departed Camp Bravo at 0530 and was scheduled to arrive at Forward Operating Base Delta by 1100. Due to a road obstruction caused by a landslide, the convoy was forced to take an alternative route, adding approximately 45 minutes to the journey. The convoy commander reported the delay to headquarters and requested updated arrival time confirmation.", question: "What caused the convoy's delay?", options: ["A vehicle breakdown", "Enemy activity on the main road", "A landslide blocking the road", "Bad weather conditions"], answer: 2, ex: "'A road obstruction caused by a landslide' — paraphrase comprehension: the question asks for the cause, not the route change." },
    { topic: "Humanitarian medical support", passage: "NATO medical teams established a field hospital near the town of Brcko to support the local civilian population affected by flooding. The facility treated over 300 patients in the first 48 hours. Medical staff worked in 12-hour shifts to maintain continuous coverage. Supplies were replenished daily by helicopter, as road access remained limited due to flood damage.", question: "Why were supplies delivered by helicopter?", options: ["It was faster than road transport", "Road access was limited due to flood damage", "The roads were controlled by hostile forces", "Helicopter transport was cheaper"], answer: 1, ex: "'Supplies were replenished daily by helicopter, as road access remained limited due to flood damage' — 'as' = because." },
    { topic: "Training exercise overview", passage: "Exercise NORTHERN STAR is a multinational training exercise scheduled to take place over two weeks in northern Norway. Participating nations include Norway, the United Kingdom, Canada, and Italy. The exercise will focus on cold-weather operations and interoperability between national forces. Approximately 4,000 personnel will take part. Live-fire training will be conducted only at designated ranges.", question: "What is the main focus of the exercise?", options: ["Equipment testing", "Cold-weather operations and interoperability", "Recruit training", "Medical evacuation procedures"], answer: 1, ex: "'The exercise will focus on cold-weather operations and interoperability between national forces' — direct statement of focus areas." },
    { topic: "Communication protocols", passage: "All units must follow standard NATO radio procedures when transmitting operational information. Messages should be brief and clearly structured. Sensitive information must not be transmitted in clear text and must be encoded prior to transmission. If communication is lost, units should attempt contact every five minutes using the alternate frequency specified in the communication plan.", question: "What should units do with sensitive information before transmitting?", options: ["Send it via courier", "Transmit it quickly on the main frequency", "Encode it prior to transmission", "Wait for authorisation from headquarters"], answer: 2, ex: "'Sensitive information must not be transmitted in clear text and must be encoded prior to transmission' — Level 2 procedure comprehension." },
    { topic: "Border patrol incident", passage: "During a routine border patrol, a UN observer team detected unauthorised movement across the demarcation line. The team reported the incident through standard reporting channels and continued observation from a safe distance. Local authorities were notified within ten minutes. The observers did not engage and waited for further instructions from the mission commander.", question: "What did the observer team do after detecting the unauthorised movement?", options: ["They engaged immediately", "They reported and continued observation from a safe distance", "They withdrew from the area", "They requested air support"], answer: 1, ex: "'The team reported the incident... and continued observation from a safe distance' — observers in UN missions follow strict report-not-engage rules." },
    { topic: "Equipment failure report", passage: "Following the recent exercise, three units reported failures of their thermal imaging equipment. Initial investigation suggests the failures occurred due to extreme cold conditions during night operations. The manufacturer has been contacted and is sending technical specialists. Until the issue is resolved, affected units will use alternative night vision equipment from the unit reserve.", question: "What will affected units use until the equipment is repaired?", options: ["No night vision equipment", "Alternative night vision equipment from reserve stocks", "Equipment borrowed from allied forces", "Day-only operations"], answer: 1, ex: "'Affected units will use alternative night vision equipment from the unit reserve' — interim solution comprehension." },
    { topic: "Civil affairs project", passage: "The civil affairs team has launched a project to repair the damaged school in the local community. The project includes replacing the roof, fixing broken windows, and providing new desks and chairs. Local workers have been hired to assist with the construction. The project is expected to be completed within three weeks. Funding is provided through NATO civil cooperation funds.", question: "Who is performing the construction work?", options: ["NATO military engineers only", "Local civilian contractors only", "Local workers hired to assist", "Volunteers from neighbouring villages"], answer: 2, ex: "'Local workers have been hired to assist with the construction' — civil-military cooperation often involves hiring local labour to support both reconstruction and the local economy." },
    { topic: "Intelligence summary", passage: "The intelligence summary for the week reports increased activity in the eastern sector. A small armed group has been observed conducting reconnaissance along Route Yellow on three separate occasions. The group has not engaged with patrols. However, their pattern of activity suggests preparation for future operations. All patrols in the area are advised to maintain heightened vigilance.", question: "What is suggested by the armed group's pattern of activity?", options: ["They are withdrawing from the area", "They are preparing for future operations", "They are engaging in humanitarian work", "They have established a permanent base"], answer: 1, ex: "'Their pattern of activity suggests preparation for future operations' — interpretation of intelligence indicators is core to Level 2 reading." },
    { topic: "Field hospital operations", passage: "The field hospital handles all medical emergencies in the operational area. The facility has 50 beds and three operating theatres. Medical staff includes general surgeons, anaesthetists, and trauma specialists. Helicopter medevac is available 24 hours a day. Patients requiring specialised treatment are transferred to the regional hospital after stabilisation.", question: "What happens to patients who need specialised treatment?", options: ["They remain at the field hospital", "They are sent home to recover", "They are transferred to the regional hospital after stabilisation", "They are flown to their home countries"], answer: 2, ex: "'Patients requiring specialised treatment are transferred to the regional hospital after stabilisation' — 'after stabilisation' is a key sequencing detail." },
    { topic: "Supply chain disruption", passage: "Recent severe weather has disrupted the supply chain to forward bases. Three convoys have been delayed by an average of 36 hours. Helicopter resupply has been limited due to poor visibility. Stocks of fuel and rations remain adequate for seven days at current consumption rates. The situation is being closely monitored and contingency plans are being prepared.", question: "How long will current stocks last at current consumption rates?", options: ["Three days", "Five days", "Seven days", "Two weeks"], answer: 2, ex: "'Stocks of fuel and rations remain adequate for seven days at current consumption rates' — note 'at current consumption rates' as a key conditional." },
    { topic: "Joint patrol procedure", passage: "Joint patrols with local security forces are conducted twice weekly. Each patrol includes four NATO soldiers and four local officers. The patrol commander is rotated between the two forces. Patrols cover a fixed route and last approximately three hours. The aim is to build trust with the local population and improve security cooperation.", question: "How is the patrol commander selected?", options: ["The senior NATO officer always commands", "The local officer always commands", "Command rotates between the two forces", "Command is shared at all times"], answer: 2, ex: "'The patrol commander is rotated between the two forces' — note that rotation differs from sharing or fixed assignment." },
    { topic: "Casualty evacuation drill", passage: "All combat units conducted a casualty evacuation drill last week. The exercise tested the speed and effectiveness of medical response. Average evacuation time from point of injury to medical facility was 45 minutes. The target is 30 minutes. Areas for improvement include radio communication delays and helicopter response times. Additional training is scheduled for next month.", question: "What is the target evacuation time?", options: ["15 minutes", "30 minutes", "45 minutes", "60 minutes"], answer: 1, ex: "'The target is 30 minutes' — note the contrast: actual time was 45 minutes, target is 30 minutes. Level 2 often tests this kind of contrast." },
    { topic: "Operational briefing format", passage: "All operational briefings follow a standard format. The first section covers the situation, including weather, terrain, and enemy activity. The second section presents the mission objective. The third section details execution, including timings, routes, and assigned tasks. The final section covers logistics and command relationships. Questions are taken at the end.", question: "What is presented in the second section of the briefing?", options: ["Weather and terrain", "The mission objective", "Logistics arrangements", "Command relationships"], answer: 1, ex: "'The second section presents the mission objective' — sequence comprehension. The standard NATO briefing format follows: Situation, Mission, Execution, Logistics/Command." },
    { topic: "Live-fire safety briefing", passage: "Before any live-fire exercise, all participants attend a mandatory safety briefing. The briefing covers weapon handling, range procedures, and emergency stop signals. Anyone who misses the briefing cannot participate in the exercise. Range officers conduct safety checks before, during, and after firing. All personnel must wear ear and eye protection at all times on the range.", question: "What is the consequence of missing the safety briefing?", options: ["A formal warning", "Cannot participate in the exercise", "Must attend a later session", "A fine"], answer: 1, ex: "'Anyone who misses the briefing cannot participate in the exercise' — direct consequence statement. Level 2 tests understanding of rules and consequences." },
  ],
  3: [
    { topic: "NATO Article 5 — collective defence", passage: "Article 5 of the North Atlantic Treaty constitutes the cornerstone of NATO's collective defence framework. It stipulates that an armed attack against one or more member nations shall be considered an attack against the alliance as a whole. Member states are obligated to take such action as they deem necessary, including the use of armed force, to restore and maintain the security of the North Atlantic area. The article has been invoked only once in NATO's history, following the terrorist attacks of 11 September 2001 in the United States. The decision to invoke Article 5 was unanimous among the then 19 member states. The collective response included the deployment of NATO AWACS aircraft to patrol American airspace and the launch of Operation Active Endeavour in the Mediterranean. The historic invocation demonstrated the practical reality of the alliance's commitment to mutual defence.", question: "On which occasion has Article 5 been invoked?", options: ["During the 1999 Kosovo crisis", "Following the September 11 attacks in the US", "During the 2003 invasion of Iraq", "After the 2014 annexation of Crimea"], answer: 1, ex: "'The article has been invoked only once in NATO's history, following the terrorist attacks of 11 September 2001.' Level 3 requires identifying specific historical facts embedded within complex formal sentences." },
    { topic: "Air superiority — Italian Air Force", passage: "Air superiority is the degree of dominance in air battle by one force that permits the conduct of its operations at a given time and place without prohibitive interference by the opposing force. Achieving and maintaining air superiority is a fundamental prerequisite for the success of joint military operations. Modern air superiority campaigns involve a combination of suppression of enemy air defences, counter-air operations, and electronic warfare. The Italian Air Force has developed significant expertise in air superiority roles through participation in NATO operations, including deployments to the Baltic Air Policing mission. This rotational mission, in which allied air forces patrol the airspace of Estonia, Latvia, and Lithuania, demonstrates alliance solidarity with member states that lack their own combat aviation capability. The mission has continued without interruption since 2004 and represents one of NATO's most visible peacetime commitments.", question: "According to the text, what is required for joint military operations to succeed?", options: ["Numerical superiority in ground forces", "Achieving and maintaining air superiority", "Access to advanced electronic warfare systems", "Strong logistical support networks"], answer: 1, ex: "'Achieving and maintaining air superiority is a fundamental prerequisite for the success of joint military operations.' 'Prerequisite' = essential requirement. Level 3 vocabulary comprehension." },
    { topic: "Cyber security — hybrid warfare", passage: "Modern hybrid warfare combines conventional military operations with cyber attacks, disinformation campaigns, and economic pressure. NATO has recognised cyber space as an operational domain alongside land, sea, air, and space. Member nations are developing national cyber defence capabilities and are expected to contribute to collective cyber resilience. A significant cyber incident can trigger consultations under Article 4 of the North Atlantic Treaty, and, in severe cases, may be deemed equivalent to an armed attack, potentially invoking Article 5. The challenge lies in attributing cyber attacks to specific state or non-state actors, a process that is often complex and time-consuming. Without clear attribution, the alliance faces difficulty in determining proportionate responses. This challenge is compounded by the fact that adversaries deliberately employ tactics designed to maintain plausible deniability.", question: "What is described as the primary challenge in responding to cyber attacks?", options: ["The high cost of cyber defence systems", "The difficulty of attributing attacks to specific actors", "The lack of legal framework for cyber warfare", "The absence of NATO cyber defence units"], answer: 1, ex: "'The challenge lies in attributing cyber attacks to specific state or non-state actors' — Level 3 tests understanding of nuanced arguments and abstract concepts." },
    { topic: "Peacekeeping evolution — civilian protection", passage: "United Nations Security Council Resolution 1674, adopted in 2006, reaffirmed the international community's responsibility to protect civilians in armed conflict. Under this framework, peacekeeping forces are not merely observers but are mandated to take active measures to prevent violations of international humanitarian law. This represents a significant evolution from the traditional peacekeeping model, in which forces were expected to maintain neutrality and use force only in strict self-defence. The new approach has been controversial. Critics argue that the expanded mandate blurs the distinction between peacekeeping and peace enforcement, potentially compromising the perceived impartiality of UN operations. Supporters counter that the moral imperative to protect civilians outweighs concerns about traditional doctrine. The debate reflects broader tensions in modern international intervention.", question: "How has the role of peacekeeping forces changed under Resolution 1674?", options: ["Forces are now required to remain strictly neutral", "Forces are mandated to actively prevent violations, not merely observe", "Forces may now initiate offensive operations without UN approval", "Forces have been given greater financial resources for operations"], answer: 1, ex: "Contrast question: traditional peacekeeping (observation + strict self-defence) vs new mandate (active prevention). Level 3 frequently tests this kind of historical contrast." },
    { topic: "Environmental military operations", passage: "Contemporary military doctrine increasingly acknowledges the environmental impact of operations. Fuel consumption, waste management, and the use of hazardous materials present both operational challenges and legal obligations under international environmental agreements. NATO's Environmental Protection Best Practices aim to minimise the ecological footprint of alliance activities without compromising operational effectiveness. Member nations are encouraged to adopt green technologies, including renewable energy sources at forward operating bases, which can also reduce logistical vulnerabilities associated with fuel supply chains. Solar installations have proven particularly effective in remote locations where fuel resupply is costly and dangerous. The dual benefits — environmental and operational — have accelerated investment in renewable technologies across multiple member nations.", question: "Why does the text suggest that adopting renewable energy at forward operating bases is beneficial?", options: ["It is required by international law", "It reduces both environmental impact and logistical vulnerability", "It completely eliminates the need for fuel convoys", "It improves relations with local civilian populations"], answer: 1, ex: "Two reasons given: environmental (ecological footprint) and operational (reducing logistical vulnerabilities). Level 3 requires synthesising two related arguments." },
    { topic: "Multinational command structures", passage: "Effective command in multinational operations is complicated by disparities in doctrine, interoperability limitations, national caveats, and divergent risk tolerances among contributing nations. The principle of unity of command, while theoretically optimal, is frequently subordinated to political considerations that produce compromise command arrangements. National caveats — restrictions placed by individual nations on how their forces may be employed — can significantly limit operational flexibility. Research into recent NATO-led operations suggests that mission success correlates more strongly with the quality of liaison mechanisms and shared situational awareness than with formal command hierarchy per se. This finding has prompted renewed emphasis on the development of common operational pictures and real-time information sharing protocols at the operational and tactical levels.", question: "According to the text, what factor correlates most strongly with mission success in multinational operations?", options: ["A strict formal command hierarchy", "Numerical superiority in personnel", "Quality of liaison mechanisms and shared situational awareness", "Standardised doctrine across all contributing nations"], answer: 2, ex: "'Mission success correlates more strongly with the quality of liaison mechanisms and shared situational awareness than with formal command hierarchy per se.' 'Per se' = in itself. Level 3 analytical comprehension." },
    { topic: "Information operations and disinformation", passage: "Information operations have become a critical dimension of modern conflict. State and non-state actors increasingly employ disinformation campaigns to undermine adversary decision-making, erode public trust, and create confusion in target populations. Social media platforms have amplified the reach and speed of these campaigns. NATO has established specialised centres to monitor and counter hostile information activities, including the Strategic Communications Centre of Excellence in Riga. Effective response requires not only technical capabilities to detect and attribute disinformation, but also the development of resilient information ecosystems within member societies. Public education in media literacy is increasingly recognised as a strategic security priority.", question: "What does the text identify as a strategic security priority?", options: ["Restricting access to social media platforms", "Public education in media literacy", "Increased military spending on cyber defence", "Banning encrypted communications"], answer: 1, ex: "'Public education in media literacy is increasingly recognised as a strategic security priority' — direct claim that requires close reading of the final sentence." },
    { topic: "Special operations doctrine", passage: "Special operations forces are characterised by their selection criteria, training intensity, and operational autonomy. They are typically employed in roles unsuitable for conventional forces, including direct action against high-value targets, special reconnaissance, military assistance to partner forces, and counter-terrorism operations. Their value derives from the ability to achieve strategic effects with limited footprints. However, this same autonomy creates challenges for oversight and integration with broader operational plans. Recent doctrine emphasises the need for clear boundaries between special operations and conventional military activities, while preserving the flexibility that makes such forces uniquely effective. The balance is delicate and remains the subject of ongoing debate within alliance forums.", question: "What is identified as the value of special operations forces?", options: ["Their large numerical strength", "The ability to achieve strategic effects with limited footprints", "Their lower operational costs", "Their flexibility in defensive operations"], answer: 1, ex: "'Their value derives from the ability to achieve strategic effects with limited footprints' — 'footprint' = visible presence. Level 3 tests understanding of strategic concepts." },
    { topic: "Maritime security operations", passage: "Maritime security operations encompass a range of activities aimed at preserving freedom of navigation and protecting commercial shipping from threats including piracy, smuggling, and terrorism. NATO's Operation Sea Guardian, which succeeded Operation Active Endeavour in the Mediterranean, exemplifies this approach. The operation conducts maritime situational awareness, supports counter-terrorism activities, and contributes to capacity-building for partner navies. Coordination with European Union missions and other international actors is essential. The maritime domain presents distinctive challenges, including the vast areas to be monitored, the international legal regime governing the seas, and the variety of actors operating in maritime space. Effective operations require sustained presence, advanced surveillance capabilities, and robust legal frameworks for boarding and interdiction.", question: "What does the text identify as essential for maritime security operations?", options: ["Coordination with EU missions and other international actors", "Exclusive use of NATO assets", "Restriction of commercial shipping in conflict zones", "Permanent military presence at all major ports"], answer: 0, ex: "'Coordination with European Union missions and other international actors is essential' — direct claim. Level 3 tests careful identification of explicit assertions." },
    { topic: "Stabilisation operations theory", passage: "Stabilisation operations seek to create the conditions for sustainable peace following conflict. They typically combine security activities with political, economic, and developmental components. Experience from Afghanistan, Iraq, and the Balkans has demonstrated that purely military approaches are insufficient to address the root causes of instability. The concept of comprehensive approach emerged from these experiences, emphasising integrated civilian-military action under unified strategic direction. However, implementing this approach in practice has proved challenging. Civilian agencies and military forces operate under different cultures, timelines, and authorities. Genuine integration requires not only structural arrangements but also shared understanding of the operational environment and the desired end state.", question: "According to the text, what does effective integration of civilian and military efforts require?", options: ["Identical organisational structures", "Shared understanding of the operational environment and end state", "Military command over all civilian activities", "Separate operational areas for each component"], answer: 1, ex: "'Genuine integration requires not only structural arrangements but also shared understanding of the operational environment and the desired end state' — Level 3 comprehension of complex causal relationships." },
    { topic: "Ballistic missile defence", passage: "NATO's ballistic missile defence capability is designed to protect alliance territory and populations against missile threats from outside the Euro-Atlantic area. The system integrates contributions from multiple member nations, including radar installations, interceptor missiles, and command and control elements. The capability has been declared operational and continues to be enhanced through ongoing investment. Russia has consistently characterised the system as a strategic threat, despite NATO assurances that it is not directed against Russian forces and lacks the capability to intercept Russian intercontinental missiles. This dispute has contributed to deteriorating relations between NATO and Russia, with implications extending beyond missile defence into broader questions of strategic stability in Europe.", question: "What has the system contributed to according to the text?", options: ["Improved relations between NATO and Russia", "Reduced defence spending across the alliance", "Deteriorating relations between NATO and Russia", "The withdrawal of US forces from Europe"], answer: 2, ex: "'This dispute has contributed to deteriorating relations between NATO and Russia' — Level 3 tests understanding of cause-effect chains in geopolitical contexts." },
    { topic: "Capability development priorities", passage: "NATO's capability development priorities reflect the evolving security environment. Recent emphasis has focused on areas including cyber defence, space situational awareness, artificial intelligence, and resilience against hybrid threats. These priorities recognise that future conflicts are likely to involve simultaneous challenges across multiple domains, including those previously considered peripheral to traditional military operations. Investment decisions are guided by the NATO Defence Planning Process, which seeks to ensure that the alliance has the necessary capabilities to fulfil its core tasks of collective defence, crisis management, and cooperative security. National contributions to these capabilities are coordinated through agreed targets, although implementation has been uneven across member states.", question: "What does the text identify as guiding investment decisions?", options: ["The NATO Defence Planning Process", "Decisions made by the US Department of Defense", "Recommendations from individual member states", "United Nations Security Council resolutions"], answer: 0, ex: "'Investment decisions are guided by the NATO Defence Planning Process' — direct identification of decision-making framework." },
    { topic: "Counter-terrorism cooperation", passage: "Counter-terrorism cooperation within the alliance has evolved significantly since the 2001 attacks on the United States. NATO's role complements that of national authorities and other international bodies, focusing primarily on intelligence sharing, capability development, and partnership with countries facing terrorist threats. The alliance maintains a counter-terrorism action plan and conducts regular exercises to test collective responses. However, primary responsibility for counter-terrorism remains with national governments, reflecting both legal frameworks and the predominantly domestic nature of many terrorist threats. The challenge of balancing security imperatives with civil liberties has been particularly acute in democratic societies, where intrusive surveillance powers face legal and political constraints absent in authoritarian regimes.", question: "Where does primary responsibility for counter-terrorism reside?", options: ["With NATO headquarters", "With national governments", "With the United Nations", "With individual military commanders"], answer: 1, ex: "'Primary responsibility for counter-terrorism remains with national governments' — explicit statement of responsibility allocation." },
    { topic: "Defence industrial cooperation", passage: "Defence industrial cooperation among NATO members has long been promoted as a means to enhance interoperability, reduce costs, and strengthen the technological base of the alliance. Joint procurement programmes for major equipment have produced both successes and difficulties. Successful programmes have delivered advanced capabilities at affordable cost while building lasting industrial partnerships. Less successful efforts have been hampered by divergent national requirements, industrial protectionism, and political pressures to maintain domestic manufacturing capacity. Recent initiatives have sought to address these obstacles through more flexible cooperation frameworks. Whether these initiatives will produce sustained improvements in industrial cooperation remains uncertain, although the imperative of maximising defence resources amid competing demands provides strong motivation for continued effort.", question: "What does the text identify as a factor that has hampered less successful programmes?", options: ["Excessive standardisation across nations", "Divergent national requirements and industrial protectionism", "Insufficient funding from NATO headquarters", "Lack of technical expertise within member states"], answer: 1, ex: "'Less successful efforts have been hampered by divergent national requirements, industrial protectionism, and political pressures' — Level 3 tests identifying specific causal factors." },
    { topic: "Partnership programmes", passage: "NATO maintains formal partnership relationships with countries beyond the alliance, ranging from comprehensive frameworks such as the Partnership for Peace to more limited arrangements with individual nations. These relationships serve multiple purposes, including enhancing security cooperation, building interoperability with potential coalition partners, and projecting stability beyond the immediate Euro-Atlantic area. Partner nations have made significant contributions to NATO operations, including in Afghanistan and Kosovo. The political dimensions of partnerships have, however, become increasingly complex as the geopolitical environment has shifted. Some partnerships face pressure from competing strategic relationships, while others have evolved towards closer integration with the alliance, including potential pathways to membership.", question: "What does the text describe as having become increasingly complex?", options: ["The technical aspects of partnership programmes", "The political dimensions of partnerships", "The funding mechanisms for partner activities", "The training requirements for partner forces"], answer: 1, ex: "'The political dimensions of partnerships have... become increasingly complex' — Level 3 question testing identification of an explicitly stated trend." },
  ],
  4: [
    { topic: "Nuclear deterrence — NATO posture", passage: "NATO's nuclear deterrence posture is predicated upon the principle that the alliance will not use nuclear weapons as a first resort but retains the right to do so under extreme circumstances threatening the survival of any member state. This deliberate ambiguity, enshrined in the concept of flexible response, serves to complicate adversarial calculations and thereby enhances deterrence. The deployment of US tactical nuclear weapons in Europe, under dual-key arrangements with selected NATO allies, represents both a political commitment and a tangible capability signal. Critics of the current posture contend that ambiguity may inadvertently lower the threshold for escalation and create dangerous miscalculations during crises. Proponents argue, conversely, that clarity in declaratory policy would undermine the very uncertainty upon which deterrence fundamentally depends. The debate has acquired renewed salience following Russia's invasion of Ukraine and the explicit nuclear threats articulated by Russian leadership during the conflict. The alliance has responded by reinforcing its nuclear messaging while avoiding actions that might trigger uncontrolled escalation.", question: "What is the central argument made by proponents of NATO's deliberate nuclear ambiguity?", options: ["Clarity would make NATO's deterrence more credible", "Ambiguity increases the risk of accidental nuclear conflict", "Clear policy would undermine deterrence by removing uncertainty", "Tactical nuclear weapons are unnecessary for modern deterrence"], answer: 2, ex: "'Proponents argue that clarity in declaratory policy would undermine the very uncertainty upon which deterrence fundamentally depends.' Level 4 requires understanding complex logical arguments and distinguishing proponents from critics." },
    { topic: "NATO enlargement — geopolitics", passage: "The debate over NATO's continued enlargement has intensified in the wake of Russia's full-scale invasion of Ukraine in 2022. Proponents of an open-door policy invoke both the foundational principle of sovereign self-determination and the strategic rationale of extending the alliance's defensive perimeter to encompass states that share its values and interests. Opponents, conversely, point to the destabilising effects of perceived encirclement and caution that enlargement may provoke disproportionate responses from revisionist powers seeking to preserve their declining sphere of influence. The admission of Finland in 2023 and Sweden in 2024 marked a historic shift in Northern European security architecture, demonstrating that the alliance retains the capacity to adapt to evolving geopolitical realities. These accessions, undertaken in response to Russian aggression rather than despite it, fundamentally challenge the narrative that NATO enlargement constitutes a primarily provocative act. The strategic implications, including expanded responsibilities for collective defence in the High North, will continue to shape alliance planning for decades.", question: "What evidence does the text provide that NATO retains the capacity to adapt to geopolitical change?", options: ["The continued presence of US forces in Europe", "The development of new nuclear sharing arrangements", "The admission of Finland and Sweden to the alliance", "The establishment of new NATO headquarters in Eastern Europe"], answer: 2, ex: "'The admission of Finland in 2023 and Sweden in 2024 marked a historic shift, demonstrating that the alliance retains the capacity to adapt to evolving geopolitical realities.' Level 4: identifying specific textual evidence for a stated conclusion." },
    { topic: "Strategic communications doctrine", passage: "The strategic communications framework adopted by the alliance sought to address information asymmetries that had hitherto undermined cohesion among member states. By establishing a centralised narrative management protocol, the alliance aimed to preclude adversarial exploitation of internal disagreements while simultaneously reinforcing the credibility of its deterrence posture vis-à-vis potential aggressors. Implementation has proved more challenging than anticipated. Member states retain divergent national narratives shaped by distinct historical experiences and contemporary political imperatives. The proliferation of communication channels, including platforms outside traditional regulatory frameworks, has further complicated efforts to maintain consistent messaging. Notwithstanding these obstacles, recent initiatives suggest that incremental progress is achievable, particularly when coordinated responses to specific disinformation incidents demonstrate the practical value of collective action. The challenge remains balancing the operational requirements of effective strategic communications with the democratic imperative of free expression.", question: "What was the primary aim of the strategic communications framework?", options: ["To increase military spending among member states", "To prevent adversarial exploitation of disagreements and reinforce deterrence credibility", "To establish a new command structure", "To improve relations with non-member states"], answer: 1, ex: "Level 4: 'preclude adversarial exploitation' = prevent enemies from exploiting; 'reinforcing the credibility of its deterrence posture' = strengthening deterrence. Two coordinated objectives must both be identified." },
    { topic: "Multi-domain operations doctrine", passage: "Multi-domain operations represent a paradigmatic shift in how military campaigns are conceptualised and executed. Rather than treating air, land, sea, space, and cyber as parallel but largely independent domains, the multi-domain framework seeks to exploit convergence — the simultaneous application of effects across domains to create dilemmas for the adversary that cannot be resolved by acting in any single domain. Air power, by virtue of its speed, reach, and flexibility, remains the principal enabler of cross-domain synergy. However, realising this potential demands a level of inter-service integration and digital interoperability that most allied nations are still developing. The concept implies a fundamental rethinking of organisational structures, command arrangements, and acquisition priorities. Some critics suggest that the multi-domain construct, while intellectually compelling, risks obscuring rather than clarifying operational thinking by adding layers of complexity to already challenging coordination problems. Others argue that the framework merely articulates what skilled commanders have always sought to achieve, namely the integration of effects from all available capabilities to produce decisive operational outcomes.", question: "What does the concept of convergence in multi-domain operations mean?", options: ["Merging all military services into a single unified force", "Concentrating forces in one geographic area", "Simultaneously applying effects across domains to create irresolvable dilemmas", "Using air power as the sole means of military action"], answer: 2, ex: "'Convergence — the simultaneous application of effects across domains to create dilemmas for the adversary that cannot be resolved by acting in any single domain.' Level 4 requires correctly applying specialist terminology defined within the text." },
    { topic: "Hybrid warfare attribution", passage: "The challenge of attributing hostile actions in the contemporary security environment has acquired unprecedented complexity. Adversaries operating below the threshold of armed conflict deliberately exploit ambiguity to inhibit decisive collective response. Cyber operations conducted through chains of compromised infrastructure across multiple jurisdictions, disinformation campaigns disseminated through inauthentic networks, and economic coercion pursued through proxy entities all complicate traditional attribution frameworks. Even when technical attribution is achievable, the political will to publicly name responsible actors may be lacking, particularly when such acknowledgement implies obligations to respond. The alliance has invested in developing collective attribution mechanisms, recognising that the credibility of deterrence ultimately depends upon the demonstrated willingness to identify and respond to hostile actions regardless of the difficulty involved. Yet the asymmetry between democratic constraints and authoritarian impunity continues to favour aggressors who can maintain plausible deniability while their victims navigate transparent legal processes.", question: "According to the text, what does the credibility of deterrence ultimately depend upon?", options: ["The size of military forces", "The demonstrated willingness to identify and respond to hostile actions", "Maintaining secrecy about defence capabilities", "The unanimity of all alliance members"], answer: 1, ex: "'The credibility of deterrence ultimately depends upon the demonstrated willingness to identify and respond to hostile actions regardless of the difficulty involved' — Level 4 tests synthesis of complex argumentation." },
    { topic: "Deterrence theory evolution", passage: "Contemporary deterrence theory has evolved considerably from its Cold War origins, when nuclear-centric models predominated. The current strategic environment requires conceptual frameworks capable of addressing simultaneous challenges from peer competitors, regional powers, and non-state actors operating across the full spectrum of conflict. Tailored deterrence approaches recognise that what deters a nuclear-armed great power may be entirely irrelevant against a transnational terrorist organisation, and that what credibly threatens an authoritarian regime may not affect a democratic adversary's calculations. This proliferation of deterrence relationships imposes substantial demands on intelligence, capabilities, and policymaking capacity. The integrated deterrence concept, recently articulated in alliance doctrine, seeks to consolidate these multiple deterrence requirements within a unified strategic framework. However, the practical implementation of integrated deterrence remains contested, with debates over the relative weight to be assigned different threats and the appropriate balance between conventional, nuclear, and non-kinetic instruments.", question: "What does the text identify as a primary characteristic of tailored deterrence approaches?", options: ["Application of identical deterrence measures to all adversaries", "Recognition that different adversaries require different deterrence approaches", "Sole reliance on nuclear deterrence capabilities", "Withdrawal from deterrence relationships with weaker actors"], answer: 1, ex: "'What deters a nuclear-armed great power may be entirely irrelevant against a transnational terrorist organisation' — Level 4 requires understanding the principle behind differentiated approaches." },
    { topic: "Strategic stability and arms control", passage: "Strategic stability between nuclear-armed great powers has historically rested upon a combination of mutual vulnerability, transparency mechanisms, and arms control agreements that constrain destabilising capabilities. The progressive erosion of this architecture, evidenced by the demise of treaties including the INF and Open Skies agreements, has raised concerns about the increased risk of miscalculation during crises. Emerging technologies, including hypersonic weapons, autonomous systems, and counterspace capabilities, complicate traditional concepts of strategic stability by compressing decision timelines and blurring distinctions between conventional and nuclear capabilities. Restoring elements of the previous arms control architecture appears unlikely in the near term given current geopolitical tensions. Nevertheless, the underlying logic that motivated previous agreements — namely, that mutual restraint can serve the security interests of all parties — retains its relevance. Whether this logic can find expression in new frameworks suited to contemporary conditions remains a fundamental question for international security.", question: "What does the text suggest about the underlying logic of arms control?", options: ["It has been completely discredited by recent events", "It retains relevance despite difficult current conditions", "It applies only to nuclear weapons", "It requires complete trust between adversaries"], answer: 1, ex: "'The underlying logic that motivated previous agreements... retains its relevance' — Level 4 tests identification of an enduring principle despite changing circumstances." },
    { topic: "Civilian harm mitigation", passage: "The mitigation of civilian harm in armed conflict has emerged as a central concern in contemporary military operations, reflecting evolving legal obligations, strategic imperatives, and ethical commitments. Modern doctrine recognises that the protection of civilians is not merely a legal constraint upon military action but a strategic objective in its own right. Civilian casualties undermine the legitimacy of operations, alienate populations whose support may be essential to mission success, and provide propaganda advantages to adversaries. Implementation of robust civilian harm mitigation requires investment in intelligence, surveillance, and precision capabilities, alongside training, doctrine, and accountability mechanisms. These investments compete with other priorities in resource-constrained environments. Critics argue that despite improvements, the gap between stated commitments and operational reality remains substantial, particularly in operations conducted by partner forces with less developed civilian protection cultures. Bridging this gap is essential not only for legal and ethical reasons but for the operational effectiveness of contemporary military engagements.", question: "What does the text describe as a strategic objective in its own right?", options: ["Maximising enemy casualties", "Reducing operational costs", "The protection of civilians", "Acquiring advanced weapons"], answer: 2, ex: "'The protection of civilians is not merely a legal constraint... but a strategic objective in its own right' — Level 4 tests precise distinction between legal/strategic framings." },
    { topic: "Resilience as strategic concept", passage: "Resilience has emerged as a central concept in contemporary security thinking, reflecting recognition that prevention of all hostile actions is impossible and that the capacity to absorb, adapt to, and recover from hostile actions is therefore essential. Alliance doctrine identifies seven baseline resilience requirements covering critical infrastructure, civilian capabilities, and continuity of government. Implementation depends primarily upon national authorities, although coordination through alliance mechanisms enhances coherence and identifies gaps. Resilience requirements interact with traditional military capabilities in complex ways. Investments in resilience may reduce vulnerabilities that adversaries seek to exploit, thereby contributing to deterrence by denial. Conversely, evident gaps in resilience may incentivise hostile action by suggesting attractive targets. The conceptual challenge lies in calibrating resilience investments appropriately, given that absolute resilience is unattainable and excessive defensive measures may impose unsustainable costs on civilian society.", question: "How does the text describe the relationship between resilience and deterrence?", options: ["Resilience and deterrence are unrelated", "Resilience investments may contribute to deterrence by denial", "Resilience eliminates the need for deterrence", "Deterrence makes resilience unnecessary"], answer: 1, ex: "'Investments in resilience may reduce vulnerabilities that adversaries seek to exploit, thereby contributing to deterrence by denial' — Level 4 tests understanding of conceptual relationships." },
    { topic: "Burden sharing analysis", passage: "Burden sharing within the alliance has been a perennial source of contention since NATO's establishment, but the debate has acquired new intensity in the contemporary period. The benchmark of two percent of GDP defence expenditure, agreed at the Wales Summit in 2014, has become a politically charged metric despite its acknowledged limitations as a measure of meaningful contribution. Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made by member states. A nation might exceed the spending threshold while investing inefficiently in capabilities of marginal alliance utility, while another nation might fall below the threshold yet provide highly capable forces in critical operations. More sophisticated assessments incorporate measures of capability development, operational deployment, and acceptance of risk in alliance missions. Yet the simplicity of the spending metric ensures its continued political prominence, even as analysts debate whether the underlying rationale is best served by alternative frameworks.", question: "What limitation of the two percent GDP metric does the text identify?", options: ["It is too difficult to calculate accurately", "It does not capture the quality or operational value of contributions", "It is rejected by most member states", "It encourages excessive defence spending"], answer: 1, ex: "'Defence spending alone captures neither the quality of capabilities developed nor the operational contributions made by member states' — Level 4 tests understanding of analytical critique." },
    { topic: "Space domain operations", passage: "The recognition of space as an operational domain in 2019 reflected the increasing strategic significance of space-based capabilities and the corresponding vulnerabilities that dependence creates. Modern military operations rely heavily on space assets for communications, navigation, intelligence, and missile warning. Adversary capabilities to disrupt or destroy these assets have proliferated, including direct-ascent anti-satellite weapons, cyber attacks against ground stations, and counterspace systems exploiting electromagnetic spectrum operations. The alliance's approach to space emphasises deterrence through resilience and the development of complementary capabilities, rather than the pursuit of space-based weapons systems. This approach reflects both legal constraints under the Outer Space Treaty and the practical recognition that escalatory dynamics in space could prove difficult to control. The challenge of distinguishing peaceful from hostile activities in space, combined with the vulnerability of critical assets, makes the space domain particularly susceptible to miscalculation during crises.", question: "What approach to space does the alliance emphasise?", options: ["Deployment of space-based weapons systems", "Withdrawal from space-based operations", "Deterrence through resilience and complementary capabilities", "Exclusive reliance on commercial satellite providers"], answer: 2, ex: "'The alliance's approach to space emphasises deterrence through resilience and the development of complementary capabilities, rather than the pursuit of space-based weapons systems' — Level 4 requires understanding the explicit alternative framework." },
    { topic: "Climate change as security challenge", passage: "Climate change increasingly features in alliance security analysis, recognised as a threat multiplier that exacerbates existing vulnerabilities and creates new strategic challenges. The implications for military operations are multifaceted. Rising sea levels threaten coastal infrastructure and naval bases. Changing weather patterns affect operational tempo and equipment reliability. Resource scarcity, particularly water in vulnerable regions, can intensify competition and conflict. The opening of Arctic shipping routes alters strategic geography and creates new contested space. Beyond these direct operational impacts, climate change generates broader security challenges including mass migration, instability in fragile states, and contested access to critical resources. Responding effectively requires adaptation of military capabilities, integration of climate considerations into planning processes, and engagement with the broader political dimensions of climate-induced insecurity. The complexity of these challenges resists technical solutions and demands sustained political commitment across multiple decades.", question: "How does the text characterise climate change in security terms?", options: ["The primary military threat of the twenty-first century", "A threat multiplier that exacerbates existing vulnerabilities", "A purely civilian rather than military concern", "A challenge that has been adequately addressed"], answer: 1, ex: "'Climate change... recognised as a threat multiplier that exacerbates existing vulnerabilities and creates new strategic challenges' — Level 4 specific terminology comprehension." },
    { topic: "Technology transfer constraints", passage: "The regulation of technology transfer within and beyond the alliance reflects competing imperatives that have grown more difficult to reconcile. On one hand, the diffusion of advanced technologies among trusted partners enhances collective capabilities, supports interoperability, and strengthens defence industrial bases. On the other hand, the concentration of certain technologies provides strategic advantage that may be compromised through inadequate controls. The challenge is intensified by the dual-use nature of many emerging technologies, where commercial applications cannot be readily separated from potential military uses. Recent regulatory initiatives have sought to balance these considerations through frameworks that distinguish between trusted and non-trusted recipients, between mature and emerging technologies, and between commercial and military-specific applications. Implementation has proved difficult given the global nature of technology supply chains and the speed of technological development relative to regulatory processes. The result is an evolving regulatory landscape where uncertainty itself constitutes a constraint on legitimate cooperation while imperfectly limiting genuinely problematic transfers.", question: "What does the text identify as a key challenge in technology transfer regulation?", options: ["The lack of any regulatory framework", "The dual-use nature of many emerging technologies", "Excessive standardisation across nations", "The absence of trusted partners"], answer: 1, ex: "'The challenge is intensified by the dual-use nature of many emerging technologies' — Level 4 tests recognition of specific complicating factors in regulatory contexts." },
    { topic: "Forward presence strategic logic", passage: "The alliance's enhanced forward presence on its eastern flank embodies a strategic logic that combines deterrence with reassurance. The deployment of multinational battlegroups in the Baltic states and Poland, expanded following the 2022 invasion of Ukraine, signals collective commitment in a manner that purely national arrangements could not achieve. The multinational composition of these forces ensures that any aggression would necessarily engage multiple allies, thereby invoking the full weight of Article 5. This tripwire function complements rather than substitutes for substantial reinforcement capabilities held in higher readiness. The concept reflects lessons drawn from previous deterrence failures, where ambiguity about commitment may have contributed to miscalculation by aggressors. Critics contend that forward presence at current levels remains insufficient against potential Russian conventional forces and risks creating vulnerabilities if reinforcement is delayed. Proponents respond that combined arms deterrence rests upon credible escalation rather than local force balance, an argument that retains its essential validity even as the specific force levels are debated.", question: "What function does the multinational composition of forward forces serve?", options: ["It reduces the cost burden on any single nation", "It ensures that aggression would engage multiple allies, invoking Article 5", "It allows for rotation of national forces", "It provides language diversity for local engagement"], answer: 1, ex: "'The multinational composition... ensures that any aggression would necessarily engage multiple allies, thereby invoking the full weight of Article 5' — Level 4 tests strategic logic comprehension." },
    { topic: "Decision-making in alliance operations", passage: "Decision-making within alliance operational contexts presents distinctive challenges arising from the need to reconcile national prerogatives with collective effectiveness. Consensus-based decision-making, while protecting member sovereignty, can produce delays during crises when timely action proves essential. National caveats imposed by individual contributors limit operational flexibility and complicate planning. Reservations entered during plan approval may permit forces to be deployed but constrain how they may be employed once committed. These constraints have prompted recurrent debates about the trade-offs between alliance solidarity and operational effectiveness. Various reform proposals have addressed aspects of this tension, including streamlined approval procedures for routine matters, clearer doctrine for crisis response, and enhanced delegation to commanders for tactical decisions. Implementation has been uneven, reflecting the underlying reality that member states retain ultimate authority over their forces even within an integrated military structure. The challenge is to maximise effectiveness within the parameters that political reality imposes, rather than to seek institutional arrangements that transcend those parameters entirely.", question: "What does the text identify as the underlying reality regarding member state forces?", options: ["Member states have transferred all authority to NATO commanders", "Member states retain ultimate authority over their forces", "Forces are owned collectively by the alliance", "National authority applies only outside operational areas"], answer: 1, ex: "'Member states retain ultimate authority over their forces even within an integrated military structure' — Level 4 tests recognition of fundamental constitutional principles within alliance structures." },
  ],
};

// JFLT Vocabulary Database — 60 questions (15 per level)
// Topics aligned with NATO 27 official topic categories

